/** Playback of explicitly admitted recordings. Never synthesizes missing assets. */
const clamp=(v,min=0,max=1)=>Math.max(min,Math.min(max,Number(v)||0));
export function validateRecordingManifest(m){const issues=[];if(m?.version!==1||!Array.isArray(m.clips))return ['Invalid recording manifest'];const ids=new Set();for(const c of m.clips){if(!c.id||ids.has(c.id))issues.push('Missing or duplicate clip id');ids.add(c.id);if(!['music','voice','cue','reel'].includes(c.kind))issues.push(`Invalid kind: ${c.id}`);if(typeof c.src!=='string'||!/^assets\/[A-Za-z0-9_./%-]+$/.test(c.src)||c.src.includes('..'))issues.push(`Clip must have a local asset path: ${c.id}`);if(c.approvedForUse!==true||!c.sourceUrl||!c.license)issues.push(`Missing admission/provenance: ${c.id}`);}for(const id of [...Object.values(m.cues||{}),...Object.values(m.music||{}),...(m.voices||[]).map(v=>v.clipId)])if(!ids.has(id))issues.push(`Unknown mapping: ${id}`);return issues;}
export class RecordedAudio {
 constructor({manifestURL='assets/audio/recorded-manifest.json',fetcher=globalThis.fetch?.bind(globalThis)}={}){this.manifestURL=manifestURL;this.fetcher=fetcher;this.manifest={version:1,clips:[],cues:{},voices:[],music:{}};this.buffers=new Map();this.loading=new Map();this.active=new Set();this.generation=0;this.status='unloaded';this.musicLevel=.45;this.volume=1;this.musicId=null;this.pendingMusic=null;this.desiredMusic=null;this.musicEnabled=true;}
 attach(context,output,externalMusic=null){if(this.context===context)return;this.stop();for(const b of [this.musicBus,this.voiceBus,this.cueBus])b?.disconnect();this.context=context;this.externalMusic=externalMusic;this.output=output;this.musicBus=context.createGain();this.musicBus.gain.value=this.musicLevel;this.musicBus.connect(output);this.voiceBus=context.createGain();this.voiceBus.connect(output);this.cueBus=context.createGain();this.cueBus.connect(output);}
 async loadManifest(manifest=null){this.status='loading';try{const m=manifest||(await (await this.fetcher(this.manifestURL)).json());const errors=validateRecordingManifest(m);if(errors.length){this.status='invalid';this.errors=errors;return false;}this.manifest=m;this.status=m.clips.length?'available':'no-recordings';if(this.context)await Promise.all(m.clips.filter(c=>c.kind!=='music').map(c=>this.buffer(c.id).catch(()=>null)));return true;}catch(e){this.status='unavailable';this.errors=[String(e.message||e)];return false;}}
 clip(id){return this.manifest.clips.find(c=>c.id===id);}
 async buffer(id){if(this.buffers.has(id))return this.buffers.get(id);if(this.loading.has(id))return this.loading.get(id);const clip=this.clip(id);if(!clip||!this.context)throw Error('Recording or AudioContext unavailable');const task=(async()=>{const r=await this.fetcher(clip.src);if(!r.ok)throw Error(`Recording could not load: ${clip.id}`);const b=await this.context.decodeAudioData(await r.arrayBuffer());this.buffers.set(id,b);return b;})().finally(()=>this.loading.delete(id));this.loading.set(id,task);return task;}
 voiceId(actorId,line){return this.manifest.voices.find(v=>v.actorId===actorId&&v.line===line)?.clipId;}
 duck(){if(!this.context)return;const speaking=[...this.active].some(n=>n.kind==='voice'||n.kind==='reel');this.musicBus?.gain.setTargetAtTime(this.musicLevel*(speaking?.23:1),this.context.currentTime,.12);if(this.externalMusic){if(speaking&&this.externalBase===undefined)this.externalBase=this.externalMusic.gain.value;if(this.externalBase!==undefined)this.externalMusic.gain.setTargetAtTime(speaking?this.externalBase*.23:this.externalBase,this.context.currentTime,.12);if(!speaking)this.externalBase=undefined;}}
 async play(id,{distance=0,pan=0,loop=false,maxDistance=24,volume=1,musicRequest=false}={}){const clip=this.clip(id),c=this.context;if(!clip||!c||c.state!=='running'||distance>maxDistance)return false;if((clip.kind==='voice'||clip.kind==='reel')&&[...this.active].some(n=>n.kind==='voice'||n.kind==='reel'))return false;const generation=this.generation,requestedAt=c.currentTime;let buffer;try{buffer=await this.buffer(id);}catch(e){this.errors=[e.message];this.failedClipId=id;return false;}if(musicRequest&&(!this.musicEnabled||this.desiredMusic!==id))return false;if(generation!==this.generation||c.state!=='running'||clip.kind!=='music'&&c.currentTime-requestedAt>2)return false;if((clip.kind==='voice'||clip.kind==='reel')&&[...this.active].some(n=>n.kind==='voice'||n.kind==='reel'))return false;const source=c.createBufferSource(),gain=c.createGain(),panner=c.createStereoPanner();source.buffer=buffer;source.loop=loop;gain.gain.value=clamp(volume)*this.volume/(1+Math.max(0,distance)*.1);panner.pan.value=clamp(pan,-1,1);source.connect(gain);gain.connect(panner);panner.connect(clip.kind==='music'?this.musicBus:clip.kind==='cue'?this.cueBus:this.voiceBus);const node={source,gain,panner,id,kind:clip.kind};this.active.add(node);source.onended=()=>{this.active.delete(node);source.disconnect();gain.disconnect();panner.disconnect();this.duck();};source.start();if(clip.kind==='music'){for(const n of [...this.active])if(n!==node&&n.kind==='music'){n.gain.gain.setTargetAtTime(0,c.currentTime,.15);n.source.stop(c.currentTime+.7);}this.musicId=id;this.lastMusicId=id;}if(this.failedClipId===id)this.failedClipId=null;this.duck();return true;}
 setMood(mood){this.musicEnabled=true;const id=this.manifest.music[mood]||this.manifest.music.calm;this.desiredMusic=id;if(!id||this.musicId===id||this.pendingMusic===id)return;this.pendingMusic=id;this.play(id,{loop:true,maxDistance:Infinity,musicRequest:true}).finally(()=>{if(this.pendingMusic===id)this.pendingMusic=null;});}
 setMusic(enabled){this.musicEnabled=!!enabled;if(!enabled){this.desiredMusic=null;for(const n of [...this.active])if(n.kind==='music')try{n.source.stop();}catch{}this.musicId=null;this.pendingMusic=null;}}
 stop(){this.generation++;this.desiredMusic=null;for(const n of this.active)try{n.source.stop();}catch{}this.active.clear();this.musicId=null;this.pendingMusic=null;this.duck();}
 dispose(){this.stop();for(const b of [this.musicBus,this.voiceBus,this.cueBus])b?.disconnect();this.buffers.clear();}
}
